[
 {
  "id": "P01",
  "text": "Rewrite this paragraph of the US field services leave policy in plain English: vacation of three consecutive working days or fewer, booked at least 7 days ahead, is approved by rule."
 },
 {
  "id": "P02",
  "text": "Write a job ad for a field service technician in Denver, Colorado; EPA 608 certification required."
 },
 {
  "id": "P03",
  "text": "Q3 attrition by region for the board pack: Rockies 28%, Gulf Coast 33%, Midwest 30%."
 },
 {
  "id": "P04",
  "text": "Help me write feedback for Lena Ruiz, HW-012771, who missed two crew handovers this month."
 },
 {
  "id": "P05",
  "text": "Our Rotterdam crew has 3 women technicians; compare their overtime hours with the men's."
 },
 {
  "id": "P06",
  "text": "Summarize this fit note and tell me if he can come back on Monday."
 },
 {
  "id": "P07",
  "text": "Turn these grievance investigation notes into a findings letter. The allegation is that the supervisor changed the roster to punish him."
 },
 {
  "id": "P08",
  "text": "Is this employee's work permit still valid? It says it expires on June 30, 2027."
 },
 {
  "id": "P09",
  "text": "Update the bank details for Kerry: sort code 20-45-77, account 41234567."
 },
 {
  "id": "P10",
  "text": "Which of these twelve people are union members? Use the dues column."
 },
 {
  "id": "P11",
  "text": "Write a kind reply to the technician on crew 7 who has started chemo and wants fewer night shifts."
 },
 {
  "id": "P12",
  "text": "Write a roster note for the man who asked for Fridays off during Ramadan."
 },
 {
  "id": "P13",
  "text": "Explain how the Hartwell Grades F1 to F4 differ, for a new recruiter."
 }
]

